-- Schema-only fixture captured from deployed column types. No production data.
-- Deliberately excludes unrelated production triggers; wrapper contract tests only.
create schema auth;
create schema app_private;
create role anon;
create role authenticated;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid',true),'')::uuid $$;
create function app_private.current_auxilios_role() returns text language sql stable as $$ select nullif(current_setting('test.role',true),'') $$;
create sequence driver_service_intake_number_seq;
create sequence operator_service_number_seq;
create table public.daily_logs (
  log_id integer generated by default as identity,
  driver_id uuid,
  truck_id integer,
  log_date date default CURRENT_DATE,
  km_inicio integer,
  km_final integer,
  hora_inicio time without time zone default (now())::time without time zone,
  hora_fin time without time zone,
  in_workshop boolean default false,
  workshop_detail text,
  status character varying(10) default 'open'::character varying,
  created_at_device timestamp with time zone default now(),
  received_at timestamp with time zone default now(),
  sync_status character varying(10) default 'synced'::character varying,
  created_at timestamp with time zone default now(),
  foto_km_inicio text,
  foto_km_final text,
  patente_camion text,
  notas text,
  km_excepcion boolean default false,
  km_recorridos integer,
  grilla_motivo text,
  km_inicio_ia integer,
  km_inicio_origen text,
  km_final_ia integer,
  km_final_origen text,
  closed_at timestamp with time zone,
  updated_at timestamp with time zone,
  updated_by uuid,
  correction_reason text,
  voided_at timestamp with time zone,
  voided_by uuid,
  void_reason text,
  void_previous_status character varying(10)
);
create table public.driver_service_intake_events (
  event_id uuid default gen_random_uuid(),
  intake_id uuid,
  event_type text,
  notes text,
  details jsonb default '{}'::jsonb,
  created_by uuid,
  created_at timestamp with time zone default now()
);
create table public.driver_service_intakes (
  intake_id uuid default gen_random_uuid(),
  intake_number text default ((('ING-'::text || to_char((CURRENT_DATE)::timestamp with time zone, 'YYYYMMDD'::text)) || '-'::text) || lpad((nextval('driver_service_intake_number_seq'::regclass))::text, 5, '0'::text)),
  status text default 'pending_admin'::text,
  document_status text default 'draft'::text,
  driver_id uuid,
  truck_id integer,
  log_id integer,
  trip_id integer,
  remito_id integer,
  linked_service_id uuid,
  client_operation_id uuid,
  service_reference text,
  customer_name text,
  customer_phone text,
  customer_email text,
  vehicle_plate text,
  vehicle_make_model text,
  service_type text,
  origin text,
  destination text,
  driver_notes text,
  received_at timestamp with time zone,
  linked_at timestamp with time zone,
  linked_by uuid,
  created_at_device timestamp with time zone default now(),
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  origin_lat numeric(10,7),
  origin_lng numeric(10,7),
  destination_lat numeric(10,7),
  destination_lng numeric(10,7),
  origin_place_id text,
  destination_place_id text,
  origin_formatted_address text,
  destination_formatted_address text
);
create table public.operator_service_events (
  event_id bigint,
  service_id uuid,
  event_type text default 'status_change'::text,
  from_status text,
  to_status text,
  notes text,
  created_by uuid,
  created_at timestamp with time zone default now(),
  details jsonb default '{}'::jsonb
);
create table public.operator_services (
  service_id uuid default gen_random_uuid(),
  service_number text default ((('SRV-'::text || to_char((CURRENT_DATE)::timestamp with time zone, 'YYYYMMDD'::text)) || '-'::text) || lpad((nextval('operator_service_number_seq'::regclass))::text, 5, '0'::text)),
  status text default 'pending'::text,
  priority text default 'normal'::text,
  company_id uuid,
  branch_id uuid,
  contract_id uuid,
  rate_card_id uuid,
  service_order_number text,
  purchase_order_number text,
  requested_at timestamp with time zone default now(),
  scheduled_for timestamp with time zone default now(),
  estimated_arrival_at timestamp with time zone,
  customer_name text,
  customer_phone text,
  customer_email text,
  vehicle_plate text,
  vehicle_make_model text,
  origin text,
  destination text,
  origin_lat numeric(10,7),
  origin_lng numeric(10,7),
  destination_lat numeric(10,7),
  destination_lng numeric(10,7),
  primary_concept_id uuid,
  assigned_driver_id uuid,
  assigned_truck_id integer,
  assigned_at timestamp with time zone,
  assigned_by uuid,
  estimated_distance_km numeric(12,2) default 0,
  toll_estimate numeric(12,2) default 0,
  is_holiday boolean default false,
  currency text default 'ARS'::text,
  base_subtotal numeric(14,2) default 0,
  surcharge_total numeric(14,2) default 0,
  toll_total numeric(14,2) default 0,
  copay_total numeric(14,2) default 0,
  estimated_total numeric(14,2) default 0,
  company_estimated_total numeric(14,2) default 0,
  pricing_snapshot jsonb default '{}'::jsonb,
  operator_notes text,
  driver_instructions text,
  driver_notes text,
  cancellation_reason text,
  trip_id integer,
  remito_id integer,
  completed_at timestamp with time zone,
  cancelled_at timestamp with time zone,
  created_by uuid default auth.uid(),
  updated_by uuid default auth.uid(),
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  logistics_type text default 'own'::text,
  estimated_finish_at timestamp with time zone,
  granted_delay_minutes integer default 0,
  origin_place_id text,
  destination_place_id text,
  origin_formatted_address text,
  destination_formatted_address text,
  route_distance_meters integer,
  route_duration_seconds integer,
  route_toll_estimate numeric,
  route_toll_currency text,
  route_provider text,
  route_calculated_at timestamp with time zone,
  route_legs jsonb default '[]'::jsonb,
  billing_setting_id uuid,
  billing_base_id uuid,
  billing_snapshot jsonb default '{}'::jsonb,
  is_test boolean default false,
  category_id uuid,
  estimated_asphalt_km numeric(12,2) default 0,
  estimated_gravel_km numeric(12,2) default 0,
  billing_status text default 'not_ready'::text,
  toll_coverage_mode text,
  arrived_at timestamp with time zone,
  arrived_by uuid,
  arrival_source text,
  arrival_reason_code text,
  cancellation_reason_code text,
  cancellation_reason_detail text,
  service_origin text default 'administrative'::text,
  administrative_review_status text default 'approved'::text,
  document_status text default 'not_started'::text
);
create table public.remitos (
  remito_id integer generated by default as identity,
  nro_remito character varying(30),
  log_id integer,
  trip_id integer,
  driver_id uuid,
  nro_servicio character varying(30),
  patente character varying(15),
  marca_modelo character varying(100),
  razon_social character varying(200),
  cuit character varying(15),
  telefono character varying(30),
  email_cliente character varying(150),
  tipo_servicio character varying(80),
  origen character varying(200),
  destino character varying(200),
  km_reales integer,
  imp_peaje numeric(12,2) default 0,
  imp_excedente numeric(12,2) default 0,
  imp_otros numeric(12,2) default 0,
  imp_total_extras numeric(12,2),
  pago_1_metodo character varying(20),
  pago_1_monto numeric(12,2),
  pago_2_metodo character varying(20),
  pago_2_monto numeric(12,2),
  foto_urls text[],
  firma_imagen_url text,
  firmado_at timestamp with time zone,
  conformidad_servicio boolean default false,
  conformidad_cargos boolean default false,
  sin_danos boolean default false,
  conformidad_arrastre boolean,
  status character varying(15) default 'pendiente'::character varying,
  created_at_device timestamp with time zone default now(),
  received_at timestamp with time zone default now(),
  sync_status character varying(10) default 'synced'::character varying,
  created_at timestamp with time zone default now(),
  observaciones text,
  cliente_presente boolean default true,
  historial_ediciones jsonb default '[]'::jsonb,
  creado_por uuid,
  operator_service_id uuid,
  client_operation_id uuid,
  document_source text default 'legacy_driver'::text,
  driver_intake_id uuid,
  addons_version integer default 1,
  addons_review_status text default 'legacy'::text,
  accepted_imp_peaje numeric(14,2),
  accepted_imp_excedente numeric(14,2),
  accepted_imp_total_extras numeric(14,2),
  addons_reviewed_by uuid,
  addons_reviewed_at timestamp with time zone,
  origin_lat numeric(10,7),
  origin_lng numeric(10,7),
  destination_lat numeric(10,7),
  destination_lng numeric(10,7),
  origin_place_id text,
  destination_place_id text,
  origin_formatted_address text,
  destination_formatted_address text
);
create table public.service_module_settings (
  settings_key text default 'default'::text,
  column_order jsonb default '["service", "date", "route", "customer_vehicle", "resource", "status", "base", "km", "priority", "updated", "actions"]'::jsonb,
  column_visibility jsonb default '{"km": false, "base": false, "date": true, "route": true, "status": true, "actions": true, "service": true, "updated": false, "priority": false, "resource": true, "customer_vehicle": true}'::jsonb,
  field_modes jsonb default '{"customer_name": "optional", "vehicle_plate": "optional", "customer_email": "hidden", "customer_phone": "required", "operator_notes": "optional", "assigned_resources": "optional", "vehicle_make_model": "optional", "driver_instructions": "optional", "purchase_order_number": "hidden"}'::jsonb,
  workflow jsonb default '{"show_cancelled_in_history": true, "allow_personal_column_overrides": true}'::jsonb,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  updated_by uuid
);
create table public.trips (
  trip_id integer generated by default as identity,
  log_id integer,
  driver_id uuid,
  nro_servicio character varying(30),
  patente character varying(15),
  tipo_servicio character varying(80),
  origin character varying(200),
  destination character varying(200),
  fecha_hora_inicio timestamp with time zone,
  fecha_hora_fin timestamp with time zone,
  km_traveled integer,
  notes text,
  created_at_device timestamp with time zone default now(),
  received_at timestamp with time zone default now(),
  sync_status character varying(10) default 'synced'::character varying,
  created_at timestamp with time zone default now(),
  origin_lat numeric(10,7),
  origin_lng numeric(10,7),
  destination_lat numeric(10,7),
  destination_lng numeric(10,7),
  origin_place_id text,
  destination_place_id text,
  origin_formatted_address text,
  destination_formatted_address text
);

